    'tour.help': 'How this section works',
    'tour.home.goal.title': 'Your goal',
    'tour.home.goal.text': 'Which level do you want to reach? Pick one and the track will show the whole way there.',
    'tour.home.skills.title': 'Strengths and weaknesses',
    'tour.home.skills.text': 'The percentages come from practice tasks: how many answers are right on the first try. The more tasks, the more accurate the picture.',
    'tour.home.recommend.title': 'What to do today',
    'tour.home.recommend.text': 'One tip based on your data: homework due soon, a weak skill or a long break from practice.',
    'tour.home.schedule.title': 'Schedule',
    'tour.home.schedule.text': 'Your classes for the week ahead. Tap a lesson to open it.',
    'tour.intro.title': 'This is',
    'tour.intro.cta': 'Show me',
    'tour.intro.skip': 'Skip',
    'tour.practice.intro.text':
      'Trainers for every skill plus mini-games — practise on your own, at your own pace. We’ll show you around in a minute.',
    'tour.learn.intro.text':
      "Review what you covered in class: a map of levels from A0 to C1, with lessons inside in order. We'll show you how to get around.",
    'tour.lessons.intro.text':
      "Classes with your teacher: the next lesson and a calendar of all sessions. We'll show you where everything is.",
    'tour.hw.intro.text':
      "Assignments from your teacher: open one, attach your answer and send it for review. We'll show you how.",
    'tour.vocab.intro.text':
      "Words by level and by topic, plus your own dictionary — words you save in tasks end up there. We'll show you around in a minute.",
    'tour.plan.intro.text': "A day-by-day plan to your goal: what to do today and this week. We'll show you how to use it.",
    'tour.practice.skills.title': 'Five sections',
    'tour.practice.skills.text':
      'Listening, reading, writing, speaking and grammar. Each section has its own colour — tap one and its trainers appear below.',
    'tour.practice.levels.title': 'Material level',
    'tour.practice.levels.text':
      'Matches books, songs, situations and grammar units to the level you pick. “All” shows everything.',
    'tour.learn.map.title': 'Level map',
    'tour.learn.map.text':
      'The island is the whole path from A0 to C1. Every town on it is a level, and the map scrolls bottom to top.',
    'tour.learn.current.title': 'Your level',
    'tour.learn.current.text':
      'The map opens here. Inside a town is the lesson trail: you walk it in order, with a test at the end of a unit.',
    'tour.learn.locked.title': 'Locked towns',
    'tour.learn.locked.text': 'Higher levels open once you finish the current one.',
    'tour.lessons.tabs.title': 'Two tabs',
    'tour.lessons.tabs.text':
      'Online — classes with a teacher by schedule. Self-study — course materials for your level that you go through on your own.',
    'tour.lessons.next.title': 'Your next class',
    'tour.lessons.next.text':
      'The card on top is the upcoming lesson. When the teacher starts it, you join from right here.',
    'tour.lessons.calendar.title': 'Calendar',
    'tour.lessons.calendar.text': 'Every class of the month is here — the ones you had and the ones ahead.',
    'tour.hw.list.title': 'Your assignments',
    'tour.hw.list.text':
      'On top is what waits for you: assigned and sent back for a redo. Below — submitted and graded.',
    'tour.hw.upload.title': 'Your answer',
    'tour.hw.upload.text':
      'Attach the file with your work — a photo, a document or audio. The accepted formats are listed under the button.',
    'tour.hw.submit.title': 'Send for review',
    'tour.hw.submit.text':
      'The work goes to the teacher; the grade and the comment come back to this same card.',
    'tour.hw.back.title': 'All assignments',
    'tour.hw.back.text': 'Back to the list from here: the rest of your homework is there, submitted and graded too.',
    'tour.vocab.levels.title': 'Core vocabulary',
    'tour.vocab.levels.text':
      'Base words by English level. Your level is open, and everything below it.',
    'tour.vocab.fields.title': 'Specialist vocabulary',
    'tour.vocab.fields.text': 'The same words picked for your profession and subject: work, food, travel.',
    'tour.vocab.mine.title': 'My dictionary',
    'tour.vocab.mine.text':
      'Everything you saved while reading and practising lands here. The review trainer drills exactly these.',
