    "ieltsOb.p.quiz.a1.q": "How many sections does IELTS have?",
    "ieltsOb.p.quiz.a1.o1": "Three",
    "ieltsOb.p.quiz.a1.o2": "Four",
    "ieltsOb.p.quiz.a1.o3": "Five",
    "ieltsOb.p.quiz.a1.o4": "Six",
    "ieltsOb.p.quiz.a1.ex": "Listening, Reading, Writing and Speaking — four sections. The first three run back-to-back; Speaking may be scheduled on another day.",
    "ieltsOb.p.quiz.a2.q": "How long is the Reading section?",
    "ieltsOb.p.quiz.a2.o1": "30 minutes",
    "ieltsOb.p.quiz.a2.o2": "60 minutes plus 10 minutes to transfer answers",
    "ieltsOb.p.quiz.a2.o3": "60 minutes, with no extra transfer time",
    "ieltsOb.p.quiz.a2.o4": "45 minutes",
    "ieltsOb.p.quiz.a2.ex": "Transferring answers happens inside those 60 minutes — that is how Reading differs from Listening.",
