    "ieltsOb.p.quiz.a6.q": "How is the overall band produced?",
    "ieltsOb.p.quiz.a6.o1": "The sum of the four section bands",
    "ieltsOb.p.quiz.a6.o2": "The average of Listening and Reading",
    "ieltsOb.p.quiz.a6.o3": "The average of four sections, rounded to 0.5",
